/* Astro the mascot. Poses are embedded as data: URIs, so this one file is all the art the site needs.
   Reused from AstroLingo (trimmed from 22 poses to the 9 a shop uses). Pose names are by mood:
   astroPose("win") -> celebrate, "ok" -> thumbs, "wait" -> think, "fail" -> sad, "empty" -> sleep ... */
(function(){
"use strict";
const ART={
  avatar: "data:image/webp;base64,",
  hello: "data:image/webp;base64,",
  celebrate: "data:image/webp;base64,",
  thumbs: "data:image/webp;base64,",
  think: "data:image/webp;base64,",
  sad: "data:image/webp;base64,",
  sleep: "data:image/webp;base64,",
  guide: "data:image/webp;base64,",
  wave: "data:image/webp;base64,"
};
const MOOD={hello:"hello",win:"celebrate",ok:"thumbs",wait:"think",fail:"sad",empty:"sleep",guide:"guide",wave:"wave"};
window.ASTRO_ART=ART;
window.astroPose=function(mood,px){px=px||88;const s=ART[MOOD[mood]||mood]||ART.hello;
  return '<img class="apose" src="'+s+'" alt="" width="'+px+'" style="width:'+px+'px;height:auto;max-width:100%">'};
window.astroAv=function(px){px=px||36;
  return '<img class="aav" src="'+ART.avatar+'" alt="" width="'+px+'" height="'+px+'" style="width:'+px+'px;height:'+px+'px;border-radius:50%;object-fit:cover">'};
})();
